// Curated Agent Readability dataset — 390 AI companies across
// four canonical categories (infra, models, agents, devtools).
//
// Flagship rows are hand-scored. Long-tail rows are deterministic estimates
// (seeded from the domain) and re-scored live by the weekly rescan cron.
// Re-score any row anytime via /check?u=<domain>; embed badges link to
// /verify/<host> for the live verdict.

export type LeaderboardCategory = "infra" | "models" | "agents" | "devtools";

export const CATEGORY_LABELS: Record<LeaderboardCategory, string> = {
  infra: "Infra",
  models: "Models",
  agents: "Agents",
  devtools: "Dev Tools",
};

export interface LeaderboardEntry {
  rank?: number; // computed at render
  name: string;
  domain: string;
  category: LeaderboardCategory;
  score: number; // 0–100
  semantic: number; // 0–25
  jsonLd: number; // 0–20
  llmsTxt: number; // 0–15
  citability: number; // 0–20
  speed: number; // 0–20
  note?: string;
}

