export function getLeaderboard(category?: LeaderboardCategory): LeaderboardEntry[] {
  const filtered = category ? LEADERBOARD.filter((e) => e.category === category) : LEADERBOARD;
  return [...filtered]
    .sort((a, b) => b.score - a.score)
    .map((e, i) => ({ ...e, rank: i + 1 }));
}

export function countByCategory(): Record<LeaderboardCategory, number> {
  return {
    infra: LEADERBOARD.filter((e) => e.category === "infra").length,
    models: LEADERBOARD.filter((e) => e.category === "models").length,
    agents: LEADERBOARD.filter((e) => e.category === "agents").length,
    devtools: LEADERBOARD.filter((e) => e.category === "devtools").length,
  };
}
